EMBED_GO = r'''package web

import (
    "bytes"
    _ "embed"
)

//go:embed app.html
var appHTML []byte

//go:embed app.css
var appCSS []byte

//go:embed app.js
var appJS []byte

// IndexHTML is the single canonical Lite2API management application.
// The document, visual system, and behavior each have one source file.
var IndexHTML = buildApp(appHTML, appCSS, appJS)

func buildApp(html, css, js []byte) []byte {
    page := append([]byte(nil), html...)
    page = bytes.Replace(page, []byte("/*__APP_CSS__*/"), bytes.TrimSpace(css), 1)
    page = bytes.Replace(page, []byte("/*__APP_JS__*/"), bytes.TrimSpace(js), 1)
    return page
}
'''

